<!DOCTYPE html>
<html lang="es">
<head>
    <meta charset="UTF-8">
    <style>
        @page {
            size: letter portrait;
            margin: 0 2.95mm;
        }
        html, body {
            margin: 0;
            padding: 0;
            font-family: Arial, Helvetica, sans-serif;
            color: #000;
        }
        .pdf-header {
            position: fixed;
            top: 0;
            left: -2.95mm;
            right: -2.95mm;
            height: 18mm;
            background: #203347;
        }
        .pdf-footer {
            position: fixed;
            bottom: 0;
            left: -2.95mm;
            right: -2.95mm;
            height: 10mm;
            background: #203347;
        }
        .pdf-page-number {
            position: absolute;
            top: 3.2mm;
            right: 8mm;
            color: #fff;
            font: 10pt "Times New Roman", Times, serif;
            white-space: nowrap;
        }
        .pdf-page-number:after {
            content: "P&aacute;gina " counter(page) " de " counter(pages);
        }
        .header-clearance {
            height: 20mm;
        }
        .page + .page {
            page-break-before: always;
        }
        .form-row {
            width: 210mm;
            table-layout: fixed;
            border-collapse: collapse;
            border-spacing: 0;
            margin: 0 auto;
            padding: 0;
        }
        .form-row {
            page-break-inside: avoid;
        }
    </style>
</head>
